<?php
if ( ! defined( 'ABSPATH' ) ) { exit; } function gc_workflow_notice( $key ) { $messages = array( 'success' => 'Thank you. Your request has been received.', 'application' => 'Your Academy application has been received. The team will review it and contact you.', 'mentor' => 'Your mentorship request has been sent. Your dashboard will update when a mentor is assigned.', 'project' => 'Your impact project has been submitted for review.', 'event' => 'You are registered for this event. We have saved your details.', ); return isset( $messages[ $key ] ) ? $messages[ $key ] : $messages['success']; } function gc_workflow_submission( $type, $title, $email, $fields = array() ) { $id = wp_insert_post( array( 'post_type' => 'gc_submission', 'post_status' => 'private', 'post_title' => wp_strip_all_tags( $title ), ) ); if ( ! $id || is_wp_error( $id ) ) { return 0; } update_post_meta( $id, 'gc_form_type_label', sanitize_text_field( $type ) ); update_post_meta( $id, 'gc_email', sanitize_email( $email ) ); update_post_meta( $id, 'gc_workflow_status', 'new' ); update_post_meta( $id, 'gc_submitted_at', current_time( 'mysql' ) ); foreach ( $fields as $key => $value ) { update_post_meta( $id, 'gc_workflow_' . sanitize_key( $key ), is_array( $value ) ? wp_json_encode( $value ) : sanitize_textarea_field( $value ) ); } return (int) $id; } function gc_workflow_handlers() { if ( 'POST' !== $_SERVER['REQUEST_METHOD'] || empty( $_POST['gc_workflow_action'] ) ) { return; } $action = sanitize_key( wp_unslash( $_POST['gc_workflow_action'] ) ); if ( ! isset( $_POST['gc_workflow_nonce'] ) || ! wp_verify_nonce( sanitize_text_field( wp_unslash( $_POST['gc_workflow_nonce'] ) ), 'gc_workflow_' . $action ) ) { wp_die( 'Security check failed.', 403 ); } $redirect = wp_get_referer() ? wp_get_referer() : home_url( '/' ); $user = wp_get_current_user(); $email = $user && $user->exists() ? $user->user_email : sanitize_email( wp_unslash( $_POST['gc_email'] ?? '' ) ); if ( 'academy_apply' === $action ) { $cohort = absint( $_POST['gc_cohort_id'] ?? 0 ); $name = sanitize_text_field( wp_unslash( $_POST['gc_name'] ?? '' ) ); $phone = sanitize_text_field( wp_unslash( $_POST['gc_phone'] ?? '' ) ); if ( ! $name || ! is_email( $email ) || ! $cohort ) { wp_die( 'Please complete the required fields.', 400 ); } $id = gc_workflow_submission( 'Academy Application', $name . ' — Cohort ' . get_the_title( $cohort ), $email, array( 'name' => $name, 'phone' => $phone, 'cohort_id' => $cohort, 'motivation' => sanitize_textarea_field( wp_unslash( $_POST['gc_motivation'] ?? '' ) ), ) ); if ( $id && $user && $user->exists() ) { update_user_meta( $user->ID, 'gc_pending_cohort_application', $cohort ); } $redirect = add_query_arg( 'gc_notice', 'application', $redirect ); } if ( 'mentor_request' === $action ) { if ( ! is_user_logged_in() ) { wp_die( 'Please log in first.', 403 ); } $member = function_exists( 'gc_member_for_user' ) ? gc_member_for_user( get_current_user_id() ) : null; $id = gc_workflow_submission( 'Mentorship Request', $user->display_name . ' — Mentorship Request', $email, array( 'member_id' => $member ? $member->ID : 0, 'goal' => sanitize_textarea_field( wp_unslash( $_POST['gc_goal'] ?? '' ) ), 'focus' => sanitize_text_field( wp_unslash( $_POST['gc_focus'] ?? '' ) ), ) ); if ( $id ) { update_user_meta( get_current_user_id(), 'gc_mentorship_status', 'requested' ); } $redirect = add_query_arg( 'gc_notice', 'mentor', $redirect ); } if ( 'project_submit' === $action ) { if ( ! is_user_logged_in() ) { wp_die( 'Please log in first.', 403 ); } $title = sanitize_text_field( wp_unslash( $_POST['gc_project_title'] ?? '' ) ); if ( ! $title ) { wp_die( 'Project title is required.', 400 ); } $member = function_exists( 'gc_member_for_user' ) ? gc_member_for_user( get_current_user_id() ) : null; $id = wp_insert_post( array( 'post_type'=>'gc_project', 'post_status'=>'pending', 'post_title'=>$title, 'post_content'=>wp_kses_post( wp_unslash( $_POST['gc_project_description'] ?? '' ) ) ) ); if ( $id && ! is_wp_error( $id ) ) { update_post_meta( $id, 'gc_project_leader_id', $member ? $member->ID : 0 ); update_post_meta( $id, 'gc_project_status', 'Idea' ); update_post_meta( $id, 'gc_project_category', sanitize_text_field( wp_unslash( $_POST['gc_project_category'] ?? '' ) ) ); } $redirect = add_query_arg( 'gc_notice', 'project', $redirect ); } if ( 'event_register' === $action ) { if ( ! is_user_logged_in() ) { wp_die( 'Please log in first.', 403 ); } $event = absint( $_POST['gc_event_id'] ?? 0 ); $id = gc_workflow_submission( 'Event Registration', $user->display_name . ' — ' . get_the_title( $event ), $email, array( 'user_id'=>get_current_user_id(), 'event_id'=>$event ) ); if ( $id ) { update_user_meta( get_current_user_id(), 'gc_event_' . $event, 'registered' ); } $redirect = add_query_arg( 'gc_notice', 'event', $redirect ); } wp_safe_redirect( $redirect ); exit; } add_action( 'template_redirect', 'gc_workflow_handlers', 1 ); function gc_workflow_submission_meta_box() { add_meta_box( 'gc_workflow_status', 'Workflow Status', 'gc_workflow_submission_meta_box_html', 'gc_submission', 'side', 'high' ); } add_action( 'add_meta_boxes', 'gc_workflow_submission_meta_box' ); function gc_workflow_submission_meta_box_html( $post ) { wp_nonce_field( 'gc_workflow_status_save', 'gc_workflow_status_nonce' ); $status = get_post_meta( $post->ID, 'gc_workflow_status', true ) ?: 'new'; $options = array( 'new'=>'New', 'review'=>'Under Review', 'shortlisted'=>'Shortlisted', 'accepted'=>'Accepted', 'rejected'=>'Rejected', 'contacted'=>'Contacted', 'completed'=>'Completed' ); echo '<select name="gc_workflow_status" style="width:100%">'; foreach ( $options as $value=>$label ) { echo '<option value="'.esc_attr($value).'" '.selected($status,$value,false).'>'.esc_html($label).'</option>'; } echo '</select>'; } function gc_save_workflow_submission_status( $post_id ) { if ( 'gc_submission' !== get_post_type( $post_id ) || ! isset($_POST['gc_workflow_status_nonce']) || ! wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['gc_workflow_status_nonce'])),'gc_workflow_status_save') || ! current_user_can('edit_post',$post_id) ) { return; } update_post_meta( $post_id, 'gc_workflow_status', sanitize_key(wp_unslash($_POST['gc_workflow_status'] ?? 'new')) ); } add_action( 'save_post_gc_submission', 'gc_save_workflow_submission_status' ); function gc_workflow_public_notice() { if ( empty( $_GET['gc_notice'] ) ) { return; } $key = sanitize_key( wp_unslash( $_GET['gc_notice'] ) ); echo '<div class="gc-workflow-notice" role="status">' . esc_html( gc_workflow_notice( $key ) ) . '</div>'; } function gc_render_academy_application_form( $cohort_id ) { if ( ! $cohort_id ) { return; } $user = wp_get_current_user(); echo '<form class="gc-workflow-form" method="post">'; echo '<h3>Apply for this cohort</h3><p>Complete the short application below. We will contact shortlisted applicants.</p>'; echo '<input type="hidden" name="gc_workflow_action" value="academy_apply"><input type="hidden" name="gc_cohort_id" value="'.esc_attr($cohort_id).'">'; wp_nonce_field( 'gc_workflow_academy_apply', 'gc_workflow_nonce' ); echo '<label>Name<input required name="gc_name" value="'.esc_attr($user && $user->exists() ? $user->display_name : '').'"></label>'; echo '<label>Email<input required type="email" name="gc_email" value="'.esc_attr($user && $user->exists() ? $user->user_email : '').'" '.($user && $user->exists()?'readonly':'').'></label>'; echo '<label>Phone<input name="gc_phone"></label>'; echo '<label>Why do you want to join?<textarea required name="gc_motivation" rows="5"></textarea></label>'; $fee=(int)get_post_meta($cohort_id,'gc_cohort_fee',true);$required=get_post_meta($cohort_id,'gc_cohort_payment_required',true); if($fee){echo '<div class="gc-cohort-apply-payment"><strong>Cohort fee: ₦'.esc_html(number_format_i18n($fee)).'</strong>';if($required)echo '<span>Payment is required for this cohort. Pay securely or use the bank-transfer details before submitting.</span>';if(function_exists('gc_payment_box'))gc_payment_box($fee,'GC-COHORT-'.absint($cohort_id).'-'.get_current_user_id());echo '</div>';} echo '<button class="gc-button gc-button-gold" type="submit">Submit application</button></form>'; } 